public class Solution {
    public boolean isPowerOfThree(int n) {
        // If n is less than or equal to zero, then it cannot be a power of three
        if (n <= 0) {
            return false;
        }

        // Check if n is a multiple of 3
        while (n % 3 == 0) {
            n /= 3; // Divide by 3 and discard remainder
        }

        // If n is not a multiple of 3, then it cannot be a power of three
        return n == 1;
    }
}
